CREATE COLUMN TABLE "TEST_AP"."UKD1" ("TableName" NVARCHAR(20) NOT NULL , "KeyId" SMALLINT CS_INT NOT NULL , "SubKeyId" SMALLINT CS_INT NOT NULL , "ColAlias" NVARCHAR(18), PRIMARY KEY ("TableName", "KeyId", "SubKeyId")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."UKD1" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$TableName$ColAlias$','TableName','ColAlias'));
